begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values
('af300000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f3-owner@example.test',now(),now(),now()),
('af300000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f3-finance@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf300000-0000-4000-8000-000000000001','F3 fictício','f3-synthetic','active'),('bf300000-0000-4000-8000-000000000002','F3 outro','f3-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values
('cf300000-0000-4000-8000-000000000001','bf300000-0000-4000-8000-000000000001','Sede F3','sede','headquarters'),
('cf300000-0000-4000-8000-000000000002','bf300000-0000-4000-8000-000000000001','Campus F3','campus','campus'),
('cf300000-0000-4000-8000-000000000003','bf300000-0000-4000-8000-000000000002','Outra F3','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf300000-0000-4000-8000-000000000001','af300000-0000-4000-8000-000000000001','owner','active','cf300000-0000-4000-8000-000000000001'),('bf300000-0000-4000-8000-000000000001','af300000-0000-4000-8000-000000000002','finance','active','cf300000-0000-4000-8000-000000000001');
select set_config('f3.org','bf300000-0000-4000-8000-000000000001',true);
select set_config('f3.unit','cf300000-0000-4000-8000-000000000001',true);
select set_config('f3.actor','af300000-0000-4000-8000-000000000001',true);
select ok(not has_table_privilege('authenticated','private.finance_receiver_secrets','SELECT'),'credenciais não expostas aos clientes');
select ok(not has_table_privilege('service_role','private.finance_receiver_secrets','SELECT'),'serviço só acessa credenciais pela operação validada');
select ok(not has_function_privilege('authenticated','public.finance_receiver_server(uuid,uuid,uuid,text,jsonb)','EXECUTE'),'cliente não forja prova do provedor');
select ok(not has_function_privilege('anon','public.finance_receiver_settings(uuid,uuid,text,jsonb)','EXECUTE'),'visitante sem configurações');
select ok(not has_table_privilege('authenticated','private.finance_receivers','UPDATE'),'cliente não altera situação diretamente');
select ok(not has_function_privilege('authenticated','private.receiver_actor_allowed(uuid,uuid,uuid)','EXECUTE'),'validação interna não exposta');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af300000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.finance_f1(current_setting('f3.org')::uuid,array[current_setting('f3.unit')::uuid],'catalog','{"id":"df300000-0000-4000-8000-000000000001","kind":"account","name":"Caixa F3"}')$$,'conta financeira legítima');
select lives_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'open','{"provider":"mercado_pago","environment":"sandbox"}')$$,'abertura oficial pendente, sem simular aprovação');
select is(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')#>>'{items,0,status}','opening_external','cadastro externo não é conexão ativa');
select lives_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'open','{"provider":"mercado_pago","environment":"sandbox"}')$$,'repetir abertura não duplica conexão');
select is(jsonb_array_length(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')->'items'),1,'slot único por igreja/provedor/ambiente');
select throws_ok($$select public.finance_receiver_settings('bf300000-0000-4000-8000-000000000002','cf300000-0000-4000-8000-000000000003','list')$$,'42501',null,'não consulta outro ministério');
select throws_ok($$select public.finance_receiver_settings(null,null,'central')$$,'42501',null,'igreja não entra na visão da Central');
select throws_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'configure','{"provider":"mercado_pago","environment":"sandbox","version":1,"holderConfirmed":true}')$$,'22023',null,'não configura conta sem prova do servidor');
reset role;
select is((select count(*)::integer from private.finance_receivers where organization_id=current_setting('f3.org')::uuid),1,'apenas uma abertura persistida');
set local role service_role;
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'begin',jsonb_build_object('id','ef300000-0000-4000-8000-000000000001','environment','sandbox','stateHash',repeat('a',64),'verifier',repeat('x',64)))$$,'estado OAuth selado iniciado pelo servidor');
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'claim',jsonb_build_object('environment','sandbox','stateHash',repeat('a',64)))$$,'retorno consome estado uma vez');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'claim',jsonb_build_object('environment','sandbox','stateHash',repeat('a',64)))$$,'42501',null,'retorno repetido recusado');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'complete','{"attempt":"ef300000-0000-4000-8000-000000000001","environment":"sandbox"}')$$,'22023',null,'prova incompleta recusada');
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'complete',jsonb_build_object('attempt','ef300000-0000-4000-8000-000000000001','environment','sandbox','externalId','12345','holder','Titular fictício F3','expiresAt',now()+interval '1 hour','sealed',repeat('s',100)))$$,'prova de identidade salva em cofre privado');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'complete',jsonb_build_object('attempt','ef300000-0000-4000-8000-000000000001','environment','sandbox','externalId','12345','holder','Titular fictício F3','expiresAt',now()+interval '1 hour','sealed',repeat('s',100)))$$,'40001',null,'finalização repetida não substitui identidade');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,'bf300000-0000-4000-8000-000000000002','cf300000-0000-4000-8000-000000000003','begin','{"environment":"sandbox"}')$$,'42501',null,'serviço revalida ministério do ator');
select throws_ok($$select public.finance_receiver_server('af300000-0000-4000-8000-000000000002',current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'begin','{"environment":"sandbox"}')$$,'42501',null,'financeiro não autoriza conexão no lugar do responsável');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af300000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')#>>'{items,0,holder}','Titular fictício F3','titular real retornado, não inventado pelo cliente');
select ok(strpos(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')::text,repeat('s',100))=0,'listagem e histórico não revelam o token');
select throws_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'configure','{"provider":"mercado_pago","environment":"sandbox","version":2,"holderConfirmed":true,"account":"df300000-0000-4000-8000-000000000001","units":["cf300000-0000-4000-8000-000000000003"],"methods":["pix"]}')$$,'42501',null,'sede não atende ministério alheio');
select lives_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'configure','{"provider":"mercado_pago","environment":"sandbox","version":2,"holderConfirmed":true,"account":"df300000-0000-4000-8000-000000000001","units":["cf300000-0000-4000-8000-000000000001","cf300000-0000-4000-8000-000000000002"],"methods":["pix","card"]}')$$,'sede confirma igrejas explicitamente autorizadas');
select is(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')#>>'{items,0,status}','configured','configuração não declara recebimentos habilitados');
select throws_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'configure','{"provider":"mercado_pago","environment":"sandbox","version":2,"holderConfirmed":true}')$$,'40001',null,'configurações concorrentes exigem versão exata');
set local role service_role;
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'secret','{"environment":"sandbox","version":3}')$$,'serviço acessa segredo somente com ator válido e versão');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'refreshed',jsonb_build_object('environment','sandbox','version',3,'externalId','999','expiresAt',now()+interval '1 hour','sealed',repeat('s',100)))$$,'22023',null,'renovação não muda a identidade da conta');
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'begin',jsonb_build_object('id','ef300000-0000-4000-8000-000000000002','environment','sandbox','stateHash',repeat('b',64),'verifier',repeat('x',64)))$$,'nova autorização em andamento');
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'claim',jsonb_build_object('environment','sandbox','stateHash',repeat('b',64)))$$,'retorno reservado antes da revogação');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af300000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select lives_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'revoke','{"provider":"mercado_pago","environment":"sandbox","version":3}')$$,'revogar remove uso sem apagar histórico');
set local role service_role;
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'complete',jsonb_build_object('attempt','ef300000-0000-4000-8000-000000000002','environment','sandbox','externalId','12345','holder','Titular fictício F3','expiresAt',now()+interval '1 hour','sealed',repeat('s',100)))$$,'40001',null,'retorno atrasado não reativa conta revogada');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'secret','{"environment":"sandbox","version":4}')$$,'40001',null,'segredo inacessível após revogação');
reset role;
select is((select count(*)::integer from private.finance_receiver_secrets s join private.finance_receivers r on r.id=s.receiver_id where r.organization_id=current_setting('f3.org')::uuid),0,'cofre limpo na revogação local');
select throws_ok($$update private.finance_receiver_events set action='rewrite' where receiver_id in(select id from private.finance_receivers where organization_id=current_setting('f3.org')::uuid)$$,'42501',null,'histórico de conexão imutável');
select is((select count(*)::integer from private.finance_entries where organization_id=current_setting('f3.org')::uuid),0,'F3 não cria lançamentos financeiros nem cobranças');
set local role service_role;
select lives_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'key_complete',jsonb_build_object('provider','asaas','environment','sandbox','version',0,'externalId','asaas:'||repeat('a',64),'holder','Titular Asaas fictício','expiresAt',now()+interval '1 day','sealed',repeat('z',100)))$$,'Asaas aceita prova somente do serviço');
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'key_complete',jsonb_build_object('provider','asaas','environment','sandbox','version',0,'externalId','asaas:'||repeat('a',64),'holder','Titular Asaas fictício','expiresAt',now()+interval '1 day','sealed',repeat('z',100)))$$,'40001',null,'retry de chave não sobrepõe conexão alterada');
reset role;
insert into public.platform_operators(user_id,role,full_name,active,email) values('af300000-0000-4000-8000-000000000001','owner','Operador Central fictício',true,'f3-owner@example.test');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af300000-0000-4000-8000-000000000001","role":"authenticated","aal":"aal2"}',true);
select lives_ok($$select public.finance_receiver_settings(null,null,'central')$$,'Central com segundo fator consulta conexões');
select lives_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'central_hold',jsonb_build_object('id',(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')#>>'{items,1,id}'),'version',4,'reason','Bloqueio administrativo fictício'))$$,'Central pode bloquear com justificativa');
-- Mercado Pago sorts after Asaas; select slot by provider rather than trusting display order.
select lives_ok($$select public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'revoke','{"provider":"mercado_pago","environment":"sandbox","version":5}')$$,'igreja pode descartar token de conta bloqueada');
select is((select x->>'status' from jsonb_array_elements(public.finance_receiver_settings(current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'list')->'items')x where x->>'provider'='mercado_pago'),'blocked','revogação não contorna bloqueio da Central');
set local role service_role;
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'begin',jsonb_build_object('id','ef300000-0000-4000-8000-000000000003','environment','sandbox','stateHash',repeat('c',64),'verifier',repeat('x',64)))$$,'42501',null,'não reconecta enquanto bloqueado pela Central');
reset role;
update auth.users set banned_until=now()+interval '1 day' where id=current_setting('f3.actor')::uuid;
set local role service_role;
select throws_ok($$select public.finance_receiver_server(current_setting('f3.actor')::uuid,current_setting('f3.org')::uuid,current_setting('f3.unit')::uuid,'begin','{"environment":"sandbox"}')$$,'42501',null,'suspensão atual do ator revalidada pelo servidor');
select * from finish();
rollback;
